intro:
Destructs the generator object.

Given coroutine_ as the underlying coroutine object, equivalent to:

if (coroutine_)
    coroutine_.destroy();

Note, that destroying the root generator effectively destroys the entire stack of yielded generators, because the ownership of recursively yielded generators is held in awaitable objects in the coroutine frame of the yielding generator.

examples.code:
#include <generator>
#include <stdexcept>
#include <cassert>
#include <type_traits>
#include <utility>
std::generator<int> numbers() {
    co_yield 1;
    co_yield 2;
    co_return;
}
std::generator<int> failure() {
    co_yield 0;
    throw std::runtime_error("failed");
    co_return;
}
int main() {
    auto sequence = numbers();
    auto moved = std::move(sequence);
    auto assigned = numbers();
    assigned = std::move(moved);
    auto iterator = assigned.begin();
    assert(iterator != assigned.end() && *iterator == 1);
    ++iterator;
    assert(*iterator == 2);
    ++iterator;
    assert(iterator == assigned.end());
    try {
        for (int value : failure()) {
            (void)value;
        }
        assert(false);
    } catch (const std::runtime_error &) {
    }
    // Compiler-generated calls drive promise allocation, get_return_object,
    // initial/final suspend, yield_value, return_void, exception handling, and frame
    // deletion.
}
